#include "cdx/operations.h"

const char *cdx_tool_list(void) {
    return "{\"tools\":["
    "{\"name\":\"tool_info\",\"description\":\"Cordonix version, platform and per-session document load/commit counters.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{}},\"annotations\":{\"readOnlyHint\":true}},"
    "{\"name\":\"execute_program\",\"description\":\"Run an absolute native executable with literal argv, cwd and timeout. Uses Windows Job cleanup. No shell expansion. External programs read disk, so explicitly commit memory edits first.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"program\",\"args\",\"cwd\"],\"properties\":{\"program\":{\"type\":\"string\"},\"args\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"maxItems\":512},\"cwd\":{\"type\":\"string\"},\"timeout_ms\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1800000},\"expected_exit_codes\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"}},\"stdin\":{\"type\":\"string\"},\"output_encoding\":{\"type\":\"string\",\"enum\":[\"utf-8\",\"cp936\",\"gbk\"]},\"output_limit_bytes\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":262144}}},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":true,\"idempotentHint\":false}},"
    "{\"name\":\"workspace_open\",\"description\":\"Load one source file into memory. Returns document_id, disk/memory SHA256, explicit encoding and EOL. AUTO accepts BOM/strict UTF8 only; choose cp936 for legacy files.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"path\"],\"properties\":{\"path\":{\"type\":\"string\"},\"encoding\":{\"type\":\"string\",\"enum\":[\"auto\",\"utf-8\",\"utf-8-bom\",\"utf-16-le\",\"utf-16-be\",\"cp936\",\"gbk\"]}}},\"annotations\":{\"readOnlyHint\":true}},"
    "{\"name\":\"workspace_read\",\"description\":\"Read a bounded UTF8 page from an open document without reloading disk. offset/next_offset count UTF8 bytes.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\"],\"properties\":{\"document_id\":{\"type\":\"integer\"},\"offset\":{\"type\":\"integer\",\"minimum\":0},\"limit\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":32768}}},\"annotations\":{\"readOnlyHint\":true}},"
    "{\"name\":\"workspace_edit\",\"description\":\"Exact memory-only replacement with expected current SHA and occurrence count. dry_run defaults true; false updates memory only. No encoding loss, fuzzy matches or disk writes.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\",\"expected_sha256\",\"old\",\"new\"],\"properties\":{\"document_id\":{\"type\":\"integer\"},\"expected_sha256\":{\"type\":\"string\"},\"old\":{\"type\":\"string\",\"minLength\":1},\"new\":{\"type\":\"string\"},\"expected_count\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":10000},\"dry_run\":{\"type\":\"boolean\",\"default\":true}}},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":false}},"
    "{\"name\":\"workspace_commit\",\"description\":\"Commit dirty memory to the source file after rereading disk identity and SHA. Conflict leaves disk unchanged. Preserves original encoding, BOM and EOL. One-file atomic replacement.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\"],\"properties\":{\"document_id\":{\"type\":\"integer\"}}},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":true,\"idempotentHint\":false}},"
    "{\"name\":\"workspace_convert_encoding\",\"description\":\"Lossless encoding conversion in memory, preserving Unicode text and line endings. Requires current SHA; dry_run defaults true. UTF8/UTF16/CP936; unrepresentable text is rejected. Commit separately.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\",\"expected_sha256\",\"encoding\"],\"properties\":{\"document_id\":{\"type\":\"integer\"},\"expected_sha256\":{\"type\":\"string\"},\"encoding\":{\"type\":\"string\",\"enum\":[\"utf-8\",\"utf-8-bom\",\"utf-16-le\",\"utf-16-be\",\"cp936\",\"gbk\"]},\"dry_run\":{\"type\":\"boolean\",\"default\":true}}},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":false,\"idempotentHint\":false}},"
    "{\"name\":\"workspace_status\",\"description\":\"Memory/disk revision and dirty status; no disk reload. Commit always validates external disk changes.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\"],\"properties\":{\"document_id\":{\"type\":\"integer\"}}},\"annotations\":{\"readOnlyHint\":true}},"
    "{\"name\":\"workspace_search\",\"description\":\"Search a literal UTF8 string in the memory revision, up to 100 match offsets. Returns no_match distinctly.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\",\"pattern\"],\"properties\":{\"document_id\":{\"type\":\"integer\"},\"pattern\":{\"type\":\"string\",\"minLength\":1}}},\"annotations\":{\"readOnlyHint\":true}},"
    "{\"name\":\"workspace_close\",\"description\":\"Release one document. Dirty memory requires explicit discard=true or a successful commit first. Session termination discards memory, never implicitly commits.\",\"inputSchema\":{\"type\":\"object\",\"required\":[\"document_id\"],\"properties\":{\"document_id\":{\"type\":\"integer\"},\"discard\":{\"type\":\"boolean\",\"default\":false}}},\"annotations\":{\"readOnlyHint\":false,\"destructiveHint\":true,\"idempotentHint\":false}}]}";
}
